package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class DateUtils_add_TriageGen1Test {

    @Rule
    public ExpectedException thrown = ExpectedException.none();



    @Test
    public void testAdd_days() {
        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.JANUARY, 1, 12, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        Date result = DateUtils.add(date, Calendar.DAY_OF_MONTH, 5);

        Calendar resultCal = Calendar.getInstance();
        resultCal.setTime(result);
        assertEquals(6, resultCal.get(Calendar.DAY_OF_MONTH));
        assertEquals(Calendar.JANUARY, resultCal.get(Calendar.MONTH));
        assertEquals(2023, resultCal.get(Calendar.YEAR));
    }








}

