        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.JANUARY, 1, 23, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        Date result = DateUtils.add(date, Calendar.HOUR_OF_DAY, 2);

